import{_ as o,o as a,c as i,ae as l}from"./chunks/framework.qNV68s4p.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/faq.md","filePath":"zh/guide/faq.md","lastUpdated":1776335312000}'),t={name:"zh/guide/faq.md"};function r(d,e,c,n,p,h){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="sweeteditor-是-basictextfield-的增强版吗" tabindex="-1">SweetEditor 是 <code>BasicTextField</code> 的增强版吗？ <a class="header-anchor" href="#sweeteditor-是-basictextfield-的增强版吗" aria-label="Permalink to &quot;SweetEditor 是 `BasicTextField` 的增强版吗？&quot;">​</a></h2><p>不是。</p><p>SweetEditor 是一套建立在原生编辑器内核之上的专用编辑器架构，并通过 Compose Multiplatform 暴露给业务层。</p><h2 id="sweeteditor-是否依赖-native-code" tabindex="-1">SweetEditor 是否依赖 native code？ <a class="header-anchor" href="#sweeteditor-是否依赖-native-code" aria-label="Permalink to &quot;SweetEditor 是否依赖 native code？&quot;">​</a></h2><p>是的。</p><p>整个项目基于原生编辑器 core 和 Kotlin 包装层共同工作。</p><h2 id="原生-core-基于什么项目" tabindex="-1">原生 core 基于什么项目？ <a class="header-anchor" href="#原生-core-基于什么项目" aria-label="Permalink to &quot;原生 core 基于什么项目？&quot;">​</a></h2><p>当前仓库使用的原生 core 基于：</p><ul><li><a href="https://github.com/FinalScave/OpenSweetEditor" target="_blank" rel="noreferrer">FinalScave/OpenSweetEditor</a></li></ul><h2 id="支持哪些平台" tabindex="-1">支持哪些平台？ <a class="header-anchor" href="#支持哪些平台" aria-label="Permalink to &quot;支持哪些平台？&quot;">​</a></h2><p>当前目标平台包括：</p><ul><li>Android</li><li>iOS</li><li>JVM Desktop</li><li>JS</li><li>Wasm</li></ul><h2 id="可以在-compose-multiplatform-应用里直接使用吗" tabindex="-1">可以在 Compose Multiplatform 应用里直接使用吗？ <a class="header-anchor" href="#可以在-compose-multiplatform-应用里直接使用吗" aria-label="Permalink to &quot;可以在 Compose Multiplatform 应用里直接使用吗？&quot;">​</a></h2><p>可以。</p><p>这正是 <code>editor-compose</code> 模块的主要用途。</p><h2 id="可以自定义高亮和装饰吗" tabindex="-1">可以自定义高亮和装饰吗？ <a class="header-anchor" href="#可以自定义高亮和装饰吗" aria-label="Permalink to &quot;可以自定义高亮和装饰吗？&quot;">​</a></h2><p>可以。</p><p>你可以使用：</p><ul><li><code>DecorationProvider</code></li><li><code>DecorationUpdate</code></li><li><code>DecorationSet</code></li><li>自定义 <code>textStyles</code></li></ul><h2 id="可以提供补全能力吗" tabindex="-1">可以提供补全能力吗？ <a class="header-anchor" href="#可以提供补全能力吗" aria-label="Permalink to &quot;可以提供补全能力吗？&quot;">​</a></h2><p>可以。</p><p>你可以使用：</p><ul><li><code>CompletionProvider</code></li><li><code>CompletionContext</code></li><li><code>CompletionReceiver</code></li></ul><h2 id="是否支持-copilot-inline-suggestion" tabindex="-1">是否支持 Copilot / Inline Suggestion？ <a class="header-anchor" href="#是否支持-copilot-inline-suggestion" aria-label="Permalink to &quot;是否支持 Copilot / Inline Suggestion？&quot;">​</a></h2><p>支持。</p><p>Compose 层已经提供：</p><ul><li><code>InlineSuggestion</code></li><li><code>InlineSuggestionController</code></li><li>inline action bar 行为</li></ul><h2 id="可以自定义主题和字体吗" tabindex="-1">可以自定义主题和字体吗？ <a class="header-anchor" href="#可以自定义主题和字体吗" aria-label="Permalink to &quot;可以自定义主题和字体吗？&quot;">​</a></h2><p>可以。</p><p>常用入口包括：</p><ul><li><code>rememberEditorAppearance()</code></li><li><code>rememberEditorTheme()</code></li><li><code>EditorFontConfig</code></li><li><code>applyTheme()</code></li><li><code>applySettings()</code></li></ul><h2 id="是否应该在-kotlin-里重写-core-编辑逻辑" tabindex="-1">是否应该在 Kotlin 里重写 core 编辑逻辑？ <a class="header-anchor" href="#是否应该在-kotlin-里重写-core-编辑逻辑" aria-label="Permalink to &quot;是否应该在 Kotlin 里重写 core 编辑逻辑？&quot;">​</a></h2><p>不建议。</p><p>更推荐复用 native core 的能力，让 Kotlin 侧专注于包装、状态同步和 UI 集成。</p><h2 id="平台特定代码应该放哪里" tabindex="-1">平台特定代码应该放哪里？ <a class="header-anchor" href="#平台特定代码应该放哪里" aria-label="Permalink to &quot;平台特定代码应该放哪里？&quot;">​</a></h2><p>应放在对应的 source set 中：</p><ul><li><code>androidMain</code></li><li><code>iosMain</code></li><li><code>jvmMain</code></li><li><code>webMain</code></li></ul><h2 id="去哪里看实际接入示例" tabindex="-1">去哪里看实际接入示例？ <a class="header-anchor" href="#去哪里看实际接入示例" aria-label="Permalink to &quot;去哪里看实际接入示例？&quot;">​</a></h2><p>建议先看：</p><ul><li><a href="./quick-start">快速开始</a></li><li>英文 <a href="./../../guide/api-cookbook">API Cookbook</a></li><li><a href="https://github.com/lumkit/SweetEditor-Compose/tree/main/example" target="_blank" rel="noreferrer">Example App</a></li></ul>',41)])])}const m=o(t,[["render",r]]);export{u as __pageData,m as default};
